#include "vs2013_libm_data.inc"

bool g_fma3 = true;
const Lib kLib = {kSegs, 3, 0x1800e91d8ull, &g_fma3};

double RunD(void (*fn)(Cpu&), double x, double y) {
    Cpu c;
    std::memset(&c, 0, sizeof c);
    c.lib = &kLib;
    c.mxcsr = 0x1f80;
    c.x[0].lo = B(x);
    c.x[1].lo = B(y);
    c.r[RSP] = kStackBase + kStackSize - 128;  // 16-byte aligned before the call pushes the return address
    c.r[RSP] -= 8;
    St(c, c.r[RSP], 0xdeadbeefull, 8);
    fn(c);
    return D(c.x[0].lo);
}
