double log(double x) { return RunD(f_974a0, x, 0); }
double log10(double x) { return RunD(f_979e0, x, 0); }
double pow(double x, double y) { return RunD(f_99ca0, x, y); }
double sinh(double x) { return RunD(f_9e040, x, 0); }
double tan(double x) { return RunD(f_9eb40, x, 0); }
